mapper.select:
/** saleson.shop.welfarecenter.SlaveOffgiveMapper.getManagerRequestListByParam (관리자 권한 승인관리 목록 조회) */ SELECT A.USER_ID ,A.REQST_SN ,CRYPTO_DEC('normal', A.LOGIN_ID, '', 0) AS LOGIN_ID ,A.LOCGOV_CODE ,A.REQST_SE_CODE ,A.PSITN_CODE ,A.PSITN_NM ,A.PSITN_DEPT_NM ,CRYPTO_DEC('normal', A.OFCPS_NM, '', 0) AS OFCPS_NM ,CRYPTO_DEC('normal', A.CTTPC, '', 0) AS CTTPC ,A.CONFM_STTUS_CODE ,A.REJECT_RESN ,A.FRST_REGISTER_ID ,DATE_FORMAT(A.FRST_REGIST_PNTTM,'%Y-%m-%d') AS FRST_REGIST_PNTTM ,A.LAST_UPDUSR_ID ,DATE_FORMAT(A.LAST_UPDT_PNTTM,'%Y-%m-%d') AS LAST_UPDT_PNTTM ,CRYPTO_DEC('normal', A.USER_NAME, '', 0) AS USER_NAME ,CRYPTO_DEC('normal', A.EMAIL, '', 0) AS EMAIL ,CRYPTO_DEC('normal', A.PHONE_NUMBER, '', 0) AS PHONE_NUMBER ,CRYPTO_DEC('normal', A.BIRTHDAY, '', 0) AS BIRTHDAY ,A.CONFM_STTUS_NM ,A.REQST_SE_NM ,A.LOCGOV_NM ,A.UPPER_LOCGOV_NM ,A.BANK_NM ,A.UPPER_LOCGOV_CODE , CASE WHEN A.CONFM_STTUS_CODE = '100' THEN CASE WHEN A.MANAGER_ID IS NOT NULL THEN CASE WHEN A.CHECK_REQST_SN = A.REQST_SN THEN 'Y' ELSE '권한 삭제 상태' END ELSE '권한 삭제 상태' END ELSE '미승인' END AS ACTIVE , PBADMS_WLFR_CNTR_NM FROM (
SELECT R.USER_ID, R.REQST_SN, R.LOGIN_ID, R.LOCGOV_CODE, R.REQST_SE_CODE, R.PSITN_CODE, R.PSITN_NM, R.PSITN_DEPT_NM, R.OFCPS_NM, R.CTTPC, R.CONFM_STTUS_CODE, R.REJECT_RESN, R.FRST_REGISTER_ID, R.FRST_REGIST_PNTTM, R.LAST_UPDUSR_ID, R.LAST_UPDT_PNTTM, U.USER_NAME, U.EMAIL, UD.PHONE_NUMBER, UD.BIRTHDAY, C1.LABEL AS CONFM_STTUS_NM, C2.LABEL AS REQST_SE_NM, C3.LABEL AS LOCGOV_NM, C4.LABEL AS UPPER_LOCGOV_NM, C5.LABEL AS BANK_NM, CONCAT(SUBSTR(R.LOCGOV_CODE, 1, 2), '000') AS UPPER_LOCGOV_CODE , M.USER_ID AS MANAGER_ID , MAX(REQST_SN) OVER(PARTITION BY R.USER_ID, R.LOCGOV_CODE) AS CHECK_REQST_SN , G.PBADMS_WLFR_CNTR_NM FROM G_MNGR_REQST R INNER JOIN OP_USER U ON U.USER_ID = R.USER_ID INNER JOIN OP_USER_DETAIL UD ON UD.USER_ID = U.USER_ID LEFT OUTER JOIN OP_COMMON_CODE C1 ON C1.CODE_TYPE = 'CFM_STATUS' AND C1.USE_YN = 'Y' AND C1.LANGUAGE = 'ko' AND C1.ID = R.CONFM_STTUS_CODE LEFT OUTER JOIN OP_COMMON_CODE C2 ON C2.CODE_TYPE = 'REQST_SE_CODE' AND C2.USE_YN = 'Y' AND C2.LANGUAGE = 'ko' AND C2.ID = R.REQST_SE_CODE LEFT OUTER JOIN OP_COMMON_CODE C3 ON C3.CODE_TYPE = 'LOCGOV_CODE' AND C3.USE_YN = 'Y' AND C3.LANGUAGE = 'ko' AND C3.ID = R.LOCGOV_CODE LEFT OUTER JOIN OP_COMMON_CODE C4 ON C4.CODE_TYPE = 'WDR' AND C4.USE_YN = 'Y' AND C4.LANGUAGE = 'ko' AND C4.ID = CONCAT(SUBSTR(R.LOCGOV_CODE, 1, 2), '000') LEFT OUTER JOIN OP_COMMON_CODE C5 ON C5.CODE_TYPE = 'OFF_BANK_LIST' AND C5.USE_YN = 'Y' AND C5.LANGUAGE = 'ko' AND C5.ID = R.PSITN_CODE LEFT OUTER JOIN OP_MANAGER M ON R.USER_ID = M.USER_ID AND M.LOCGOV_CODE = R.LOCGOV_CODE LEFT OUTER JOIN OP_USER_ROLE UR ON UR.USER_ID = M.USER_ID AND UR.AUTHORITY = 'ROLE_ADMIN_11' INNER JOIN G_LCLGV_PBADMS_WLFR_CNTR_MNG G ON R.PSITN_CODE = G.PBADMS_WLFR_CNTR_ID WHERE 1=1 AND R.REQST_SE_CODE = 'ROLE_ADMIN_11'
AND R.LOCGOV_CODE = #{locgovCode}
AND R.LOGIN_ID = (SELECT CRYPTO_ENC('normal', #{srchValue}, ''))
AND U.USER_NAME = (SELECT CRYPTO_ENC('normal', #{srchValue}, ''))
AND U.EMAIL = (SELECT CRYPTO_ENC('normal', #{srchValue}, ''))
AND DATE_FORMAT(R.FRST_REGIST_PNTTM,'%Y%m%d') >= #{srchStartCreated}
AND DATE_FORMAT(R.FRST_REGIST_PNTTM,'%Y%m%d') <= #{srchEndCreated}
AND CONFM_STTUS_CODE = #{srchConfmSttusCode}
ORDER BY R.FRST_REGIST_PNTTM DESC
) A

/** saleson.shop.welfarecenter.SlaveOffgiveMapper.getManagerRequestCountByParam (관리자 권한 승인관리 목록 갯수 조회) */ SELECT COUNT(*) FROM ( SELECT A.USER_ID ,A.REQST_SN ,CRYPTO_DEC('normal', A.LOGIN_ID, '', 0) AS LOGIN_ID ,A.LOCGOV_CODE ,A.REQST_SE_CODE ,A.PSITN_CODE ,A.PSITN_NM ,A.PSITN_DEPT_NM ,CRYPTO_DEC('normal', A.OFCPS_NM, '', 0) AS OFCPS_NM ,CRYPTO_DEC('normal', A.CTTPC, '', 0) AS CTTPC ,A.CONFM_STTUS_CODE ,A.REJECT_RESN ,A.FRST_REGISTER_ID ,DATE_FORMAT(A.FRST_REGIST_PNTTM,'%Y-%m-%d') AS FRST_REGIST_PNTTM ,A.LAST_UPDUSR_ID ,DATE_FORMAT(A.LAST_UPDT_PNTTM,'%Y-%m-%d') AS LAST_UPDT_PNTTM ,CRYPTO_DEC('normal', A.USER_NAME, '', 0) AS USER_NAME ,CRYPTO_DEC('normal', A.EMAIL, '', 0) AS EMAIL ,CRYPTO_DEC('normal', A.PHONE_NUMBER, '', 0) AS PHONE_NUMBER ,CRYPTO_DEC('normal', A.BIRTHDAY, '', 0) AS BIRTHDAY ,A.CONFM_STTUS_NM ,A.REQST_SE_NM ,A.LOCGOV_NM ,A.UPPER_LOCGOV_NM ,A.BANK_NM ,A.UPPER_LOCGOV_CODE , CASE WHEN A.CONFM_STTUS_CODE = '100' THEN CASE WHEN A.MANAGER_ID IS NOT NULL THEN CASE WHEN A.CHECK_REQST_SN = A.REQST_SN THEN 'Y' ELSE '권한 삭제 상태' END ELSE '권한 삭제 상태' END ELSE '미승인' END AS ACTIVE , PBADMS_WLFR_CNTR_NM FROM (
SELECT R.USER_ID, R.REQST_SN, R.LOGIN_ID, R.LOCGOV_CODE, R.REQST_SE_CODE, R.PSITN_CODE, R.PSITN_NM, R.PSITN_DEPT_NM, R.OFCPS_NM, R.CTTPC, R.CONFM_STTUS_CODE, R.REJECT_RESN, R.FRST_REGISTER_ID, R.FRST_REGIST_PNTTM, R.LAST_UPDUSR_ID, R.LAST_UPDT_PNTTM, U.USER_NAME, U.EMAIL, UD.PHONE_NUMBER, UD.BIRTHDAY, C1.LABEL AS CONFM_STTUS_NM, C2.LABEL AS REQST_SE_NM, C3.LABEL AS LOCGOV_NM, C4.LABEL AS UPPER_LOCGOV_NM, C5.LABEL AS BANK_NM, CONCAT(SUBSTR(R.LOCGOV_CODE, 1, 2), '000') AS UPPER_LOCGOV_CODE , M.USER_ID AS MANAGER_ID , MAX(REQST_SN) OVER(PARTITION BY R.USER_ID, R.LOCGOV_CODE) AS CHECK_REQST_SN , G.PBADMS_WLFR_CNTR_NM FROM G_MNGR_REQST R INNER JOIN OP_USER U ON U.USER_ID = R.USER_ID INNER JOIN OP_USER_DETAIL UD ON UD.USER_ID = U.USER_ID LEFT OUTER JOIN OP_COMMON_CODE C1 ON C1.CODE_TYPE = 'CFM_STATUS' AND C1.USE_YN = 'Y' AND C1.LANGUAGE = 'ko' AND C1.ID = R.CONFM_STTUS_CODE LEFT OUTER JOIN OP_COMMON_CODE C2 ON C2.CODE_TYPE = 'REQST_SE_CODE' AND C2.USE_YN = 'Y' AND C2.LANGUAGE = 'ko' AND C2.ID = R.REQST_SE_CODE LEFT OUTER JOIN OP_COMMON_CODE C3 ON C3.CODE_TYPE = 'LOCGOV_CODE' AND C3.USE_YN = 'Y' AND C3.LANGUAGE = 'ko' AND C3.ID = R.LOCGOV_CODE LEFT OUTER JOIN OP_COMMON_CODE C4 ON C4.CODE_TYPE = 'WDR' AND C4.USE_YN = 'Y' AND C4.LANGUAGE = 'ko' AND C4.ID = CONCAT(SUBSTR(R.LOCGOV_CODE, 1, 2), '000') LEFT OUTER JOIN OP_COMMON_CODE C5 ON C5.CODE_TYPE = 'OFF_BANK_LIST' AND C5.USE_YN = 'Y' AND C5.LANGUAGE = 'ko' AND C5.ID = R.PSITN_CODE LEFT OUTER JOIN OP_MANAGER M ON R.USER_ID = M.USER_ID AND M.LOCGOV_CODE = R.LOCGOV_CODE LEFT OUTER JOIN OP_USER_ROLE UR ON UR.USER_ID = M.USER_ID AND UR.AUTHORITY = 'ROLE_ADMIN_11' INNER JOIN G_LCLGV_PBADMS_WLFR_CNTR_MNG G ON R.PSITN_CODE = G.PBADMS_WLFR_CNTR_ID WHERE 1=1 AND R.REQST_SE_CODE = 'ROLE_ADMIN_11'
AND R.LOCGOV_CODE = #{locgovCode}
AND R.LOGIN_ID = (SELECT CRYPTO_ENC('normal', #{srchValue}, ''))
AND U.USER_NAME = (SELECT CRYPTO_ENC('normal', #{srchValue}, ''))
AND U.EMAIL = (SELECT CRYPTO_ENC('normal', #{srchValue}, ''))
AND DATE_FORMAT(R.FRST_REGIST_PNTTM,'%Y%m%d') >= #{srchStartCreated}
AND DATE_FORMAT(R.FRST_REGIST_PNTTM,'%Y%m%d') <= #{srchEndCreated}
AND CONFM_STTUS_CODE = #{srchConfmSttusCode}
ORDER BY R.FRST_REGIST_PNTTM DESC
) A )

mapper.update:
UPDATE 	G_MNGR_REQST
SET   	  PSITN_CODE = #{psitnCode}
		, PSITN_NM = #{psitnNm}

WHERE REQST_SN = #{reqstSn};

mapper.select:
/* saleson.shop.welfarecenter.WelfarecenterMapper.selectWlfrCntrMngList */ SELECT A.PBADMS_WLFR_CNTR_ID , B.UPPER_LOCGOV_CODE , A.LCLGV_CD , B.UPPER_LOCGOV_NM , B.LOCGOV_NM , A.PBADMS_WLFR_CNTR_NM , A.USE_YN , A.FRST_REG_DT FROM G_LCLGV_PBADMS_WLFR_CNTR_MNG A LEFT OUTER JOIN G_LOCGOV B ON A.LCLGV_CD = B.LOCGOV_CODE WHERE 1=1
AND LCLGV_CD = #{lclgvCd}
AND LCLGV_CD IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
AND pbadms_wlfr_cntr_nm LIKE CONCAT('%', #{pbadmsWlfrCntrNm}, '%')
AND use_yn = #{useYn}
AND frst_reg_dt >= CONCAT(#{searchStDt}, '000000')
AND frst_reg_dt <= CONCAT(#{searchEdDt}, '235959')
ORDER BY PBADMS_WLFR_CNTR_ID DESC

SELECT count(*) FROM ( SELECT A.PBADMS_WLFR_CNTR_ID , B.UPPER_LOCGOV_CODE , A.LCLGV_CD , B.UPPER_LOCGOV_NM , B.LOCGOV_NM , A.PBADMS_WLFR_CNTR_NM , A.USE_YN , A.FRST_REG_DT FROM G_LCLGV_PBADMS_WLFR_CNTR_MNG A LEFT OUTER JOIN G_LOCGOV B ON A.LCLGV_CD = B.LOCGOV_CODE WHERE 1=1
AND LCLGV_CD = #{lclgvCd}
AND LCLGV_CD IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
AND pbadms_wlfr_cntr_nm LIKE CONCAT('%', #{pbadmsWlfrCntrNm}, '%')
AND use_yn = #{useYn}
AND frst_reg_dt >= CONCAT(#{searchStDt}, '000000')
AND frst_reg_dt <= CONCAT(#{searchEdDt}, '235959')
)

