	LCLGV_CD
	, PBADMS_WLFR_CNTR_NM
	, PBADMS_WLFR_CNTR_CD
	, USE_YN
	, FRST_REG_DT
)
VALUES(
	#{lclgvCd}
	, #{pbadmsWlfrCntrNm}
	, #{pbadmsWlfrCntrCd}
	, #{useYn}
	, CURRENT_TIMESTAMP
)

