SELECT COUNT(*) AS dupCnt
FROM G_LCLGV_PBADMS_WLFR_CNTR_MNG
WHERE LCLGV_CD = #{lclgvCd}
AND PBADMS_WLFR_CNTR_NM = #{pbadmsWlfrCntrNm}

mapper.update:
UPDATE G_LCLGV_PBADMS_WLFR_CNTR_MNG SET
	PBADMS_WLFR_CNTR_NM = #{pbadmsWlfrCntrNm}
	, PBADMS_WLFR_CNTR_CD = #{pbadmsWlfrCntrCd}
	, USE_YN = #{useYn}
WHERE 1=1
AND	PBADMS_WLFR_CNTR_ID = #{pbadmsWlfrCntrId}
